          (bbatch :: x_busy X).
Hypothesis WF : awf L st X.
Hypothesis CNT : c_count (get_cls st K_BATCH_CLASS) = cnt.
Hypothesis POS : 0 < cnt.
Hypothesis NK : nth_error (xc_cache (x_cls X K_BATCH_CLASS)) (Z.to_nat (cnt - 1)) = Some k24.

