(* [comment removed for export] *)
Lemma qcoupled_drain : forall s s' X' Q' ia,
  qcoupled L s X' Q' ->
  a_qloc s' = [] -> a_qglob s' = a_qglob s ++ a_qloc s ->
  qcoupled L s' X' (mkQConc [] (q_glob Q' ++ q_loc Q') ia (q_pend Q')).
Proof.
